// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint64 warpTime, uint64 blk) public {
        vm.assume(caller != address(0));
        uint256 amt = 10 ether;

        vm.warp(uint256(warpTime));
        vm.roll(uint256(blk == 0 ? 1 : blk));

        vm.deal(caller, amt);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amt}("");

        if (uint256(block.number) % 15 != 0 && ok) {
            assertTrue(address(c).balance >= amt);
        } else {
            assertTrue(address(c).balance >= 0);
        }
    }
}
